const input = $input.first().json;
if (input.fast_intent) {
  return [{ json: { intent: input.fast_intent, content: input.fast_content } }];
}
const raw = input.response || '';
let parsed;
try {
  parsed = JSON.parse(raw);
  if (!['store','forget','correct','question','chat','task','list_tasks','complete_task','note','media_query'].includes(parsed.intent)) throw new Error('bad intent');
  if (!parsed.content) throw new Error('no content');
  if (parsed.intent === 'correct' && !parsed.old_content) throw new Error('correct needs old_content');
} catch (e) {
  parsed = { intent: 'question', content: $('Discord Message In').first().json.body.content };
}
return [{ json: parsed }];

const matches = $('Search for Match').first().json.result || [];
let reply;
if (matches.length === 0) {
  reply = `I couldn't find anything stored that matches "${$('Parse Intent').first().json.content}" — nothing was deleted.`;
} else {
  const list = matches.map(m => `"${m.payload.text}"`).join(', ');
  reply = `Forgot it. Removed: ${list}`;
}
return [{ json: { reply, logText: reply } }];

const question = $('Parse Intent').first().json.content;
const results = $('Search Qdrant').first().json.result || [];
const context = results.length
  ? results.map((r, i) => `[${i + 1}] ${r.payload.text}`).join('
')
  : '(no relevant memories found)';
const history = ($json.result?.points || []).sort((a,b) => (a.payload.added_at||'').localeCompare(b.payload.added_at||'')).slice(-4);
const historyText = history.length ? history.map(h => h.payload.text).join('
') : '(no earlier conversation today)';
const prompt = `You are Kody's second brain, a personal knowledge assistant with a warm, natural conversational style — not a search engine. Answer the question using the facts in Context below, and use Recent Conversation for continuity if the question refers back to it (e.g. "what about tomorrow", "and the other one"). If Context doesn't contain the answer, say so honestly and conversationally rather than guessing.

Context:
${context}

Recent conversation today:
${historyText}

Question: ${question}

Answer:`;
return [{ json: { prompt, question } }];

const message = $('Parse Intent').first().json.content;
const history = ($json.result?.points || []).sort((a,b) => (a.payload.added_at||'').localeCompare(b.payload.added_at||'')).slice(-4);
const historyText = history.length ? history.map(h => h.payload.text).join('
') : '(this is the start of the conversation today)';
const prompt = `You are Kody's second brain — a warm, casual, genuinely present conversational partner, not a formal assistant. This message is small talk / chat, not a request to look anything up. Reply naturally and briefly, like a text from a friend who happens to remember everything about Kody's life. Use the recent conversation for continuity if relevant.

Recent conversation today:
${historyText}

Message: ${message}

Reply:`;
return [{ json: { prompt, message } }];

const title = $('Parse Intent').first().json.content;
const ok = $json.id !== undefined;
const reply = ok ? `\u2705 Added to Vikunja: "${title}"` : `Tried to create a Vikunja task but something went wrong (check the Vikunja credential/project ID). I didn't lose the request though: "${title}"`;
return [{ json: { reply, logText: `Created Vikunja task: "${title}"` } }];

let raw = $input.all().map(i => i.json);
if (raw.length === 1 && Array.isArray(raw[0])) raw = raw[0];
const fetchFailed = raw.length > 0 && raw.every(t => t && t.error !== undefined);
const tasks = raw.filter(t => t && t.id !== undefined);
if (fetchFailed) {
  return [{ json: { reply: "I couldn't reach Vikunja to get your tasks just now \u2014 try again in a bit.", logText: 'Asked for task list, Vikunja unreachable' } }];
}
const open = tasks.filter(t => !t.done).sort((a,b) => {
  if (!a.due_date || a.due_date.startsWith('0001')) return 1;
  if (!b.due_date || b.due_date.startsWith('0001')) return -1;
  return a.due_date.localeCompare(b.due_date);
});
let reply;
if (open.length === 0) {
  reply = "You don't have any open tasks in Vikunja right now.";
} else {
  const lines = open.slice(0, 15).map(t => {
    const due = (t.due_date && !t.due_date.startsWith('0001')) ? ` (due ${t.due_date.slice(0,10)})` : '';
    return `- ${t.title}${due}`;
  });
  reply = `You have ${open.length} open task${open.length===1?'':'s'}:\n${lines.join('\n')}`;
}
return [{ json: { reply, logText: 'Asked for task list' } }];

let tasks = $input.all().map(i => i.json);
if (tasks.length === 1 && Array.isArray(tasks[0])) tasks = tasks[0];
tasks = tasks.filter(t => t && t.id !== undefined);
const fetchFailed = tasks.length === 0 && $input.all().some(i => i.json && i.json.error);
const open = tasks.filter(t => !t.done);
const described = $('Parse Intent').first().json.content;
const list = open.map(t => `${t.id}: ${t.title}`).join('\n');
const prompt = `Below is a numbered list of open tasks (id: title). The user says they completed something described as: "${described}". Respond with ONLY JSON: {"taskId": <id>, "confidence": <0.0-1.0>} if you can identify which task they mean (confidence = how sure you are), or {"taskId": null, "confidence": 0} if none match well or the list is empty.\n\nOpen tasks:\n${list || '(none)'}\n\nJSON:`;
return [{ json: { prompt, described, fetchFailed } }];

let taskId = null;
let confidence = 0;
try {
  const p = JSON.parse($json.response);
  taskId = p.taskId ?? null;
  confidence = typeof p.confidence === 'number' ? p.confidence : 0;
} catch (e) {}
const fetchFailed = $('Build Match Prompt').first().json.fetchFailed;
return [{ json: { taskId, confidence, fetchFailed, described: $('Build Match Prompt').first().json.described } }];

const t = $('Get Task By ID').first().json;
t.done = true;
return [{ json: t }];

const described = $json.described;
const reply = $json.fetchFailed
  ? `I couldn't reach Vikunja to check your tasks just now \u2014 nothing was changed. Try again in a bit.`
  : `I couldn't find an open task matching "${described}" with enough confidence \u2014 nothing was changed.`;
return [{ json: { reply, logText: `Tried to complete a task but nothing matched confidently: "${described}"` } }];

const content = $json.content;
const firstLine = content.split(/[.\n]/)[0].trim();
const title = firstLine.length > 60 ? firstLine.slice(0,57) + '...' : (firstLine || 'Note');
return [{ json: { title, body: content } }];

const ok = $json.noteId !== undefined;
const title = $('Build Note Content').first().json.title;
const reply = ok ? `\ud83d\udcdd Saved to Trilium: "${title}"` : `Tried to save that as a Trilium note but something went wrong (check the Trilium credential/parent note ID). Here's what I would've saved: "${title}"`;
return [{ json: { reply, logText: `Saved a Trilium note: "${title}"` } }];

const question = $('Parse Intent').first().json.content;
let series = [];
try { series = $('Collect Sonarr Results').first().json.seriesList || []; } catch(e) {}
let movies = [];
try { movies = $('Collect Radarr Results').first().json.movieList || []; } catch(e) {}
let history = [];
try {
  const h = $('Get Tautulli History').first().json;
  const rows = h?.response?.data?.data || [];
  history = rows.slice(0, 10).map(r => `${r.full_title || r.title} watched by ${r.friendly_name || r.user}`);
} catch(e) {}

// Fuzzy-filter the library to likely-relevant titles instead of dumping the
// whole thing into the prompt (was taking 3+ minutes and timing out on this
// CPU-only hardware with a full library in context).
const stop = new Set(['do','i','have','is','in','my','the','a','an','of','on','for','to','and','are','was','been','it','that','this','show','movie','library','watching','watched']);
const qWords = question.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/\s+/).filter(w => w.length > 2 && !stop.has(w));
function score(title) {
  const titleWords = title.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(/\s+/);
  return qWords.reduce((s,w) => s + (titleWords.includes(w) ? 1 : 0), 0);
}
const seriesMatches = series.map(s => ({ s, sc: score(s.title) })).filter(x => x.sc > 0).sort((a,b)=>b.sc-a.sc).slice(0,5)
  .map(x => `${x.s.title} (TV, ${x.s.status}, ${x.s.statistics?.episodeFileCount || 0}/${x.s.statistics?.episodeCount || 0} episodes downloaded)`);
const movieMatches = movies.map(m => ({ m, sc: score(m.title) })).filter(x => x.sc > 0).sort((a,b)=>b.sc-a.sc).slice(0,5)
  .map(x => `${x.m.title} (Movie, ${x.m.hasFile ? 'downloaded' : 'not downloaded'})`);
const historyMatches = history.filter(h => qWords.some(w => h.toLowerCase().includes(w)));

const matched = [...seriesMatches, ...movieMatches];
if (matched.length === 0 && historyMatches.length === 0 && qWords.length > 0) {
  // Confident no-match - skip the LLM call entirely, answer directly and fast.
  return [{ json: { skipLLM: true, question, directAnswer: `I don't see anything matching that in your Sonarr/Radarr library or recent Tautulli history.` } }];
}
const context = `Matching library entries:\n${matched.join('\n') || '(none found)'}\n\nMatching recent watch history:\n${historyMatches.join('\n') || '(none found)'}`;
const prompt = `You are Kody's second brain. Answer the question below using ONLY the live library/watch-history data provided as Context \u2014 this is a filtered, relevant subset of a larger library, not the whole thing, so don't comment on what's missing from Context beyond what's asked. Be concise and conversational.\n\nContext:\n${context}\n\nQuestion: ${question}\n\nAnswer:`;
return [{ json: { skipLLM: false, prompt, question } }];

function hashStr(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
const content = $json.body.content || '';
const raw = content.trim().toLowerCase().replace(/\s+/g, ' ');
return [{ json: { ...$json, content, cache_key: hashStr(raw) } }];

const content = (($json.body && $json.body.content) || '').trim();
let fast_intent = null, fast_content = null;

if (/^forget\s+/i.test(content)) {
  fast_intent = 'forget';
  fast_content = content.replace(/^forget\s+(about\s+|that\s+)?/i, '').trim();
} else if (/^remember(\s+that)?\s+/i.test(content)) {
  fast_intent = 'store';
  fast_content = content.replace(/^remember(\s+that)?\s+/i, '').trim();
} else if (/^(what tasks do i have|what'?s on my to-?do list|what is on my to-?do list|what'?s due)\??$/i.test(content)) {
  fast_intent = 'list_tasks';
  fast_content = content;
} else if (/^(remind me to|i need to)\s+/i.test(content)) {
  fast_intent = 'task';
  fast_content = content.replace(/^(remind me to|i need to)\s+/i, '').trim();
}

if (fast_content === '') { fast_intent = null; fast_content = null; }

return [{ json: { ...$json, fast_intent, fast_content } }];

const newFact = $('Parse Intent').first().json.content;
const matches = $('Search Correct (Old)').first().json.result || [];
let reply;
if (matches.length === 0) {
  reply = `Got it \u2014 I'll remember: "${newFact}"`;
} else {
  const old = matches[0].payload.text;
  reply = `Updated \u2014 replaced "${old}" with "${newFact}"`;
}
return [{ json: { reply, logText: reply } }];

const body = $input.first().json.body;
const caption = (body.content || '').trim();
return (body.images || []).map(img => ({ json: {
  url: img.url,
  filename: img.filename,
  caption,
  author_name: body.author_name,
  logText: `Photo shared by ${body.author_name}${caption ? ': ' + caption : ''} (${img.filename})`
} }));

